<template><div class="report-actions"><el-button link type="primary" @click="$emit('detail')">详情</el-button><el-dropdown v-if="row.status==='completed'" trigger="click" :disabled="downloading" @command="$emit('report',$event)"><el-button link type="success" :loading="downloading">{{downloading?'生成中…':'报告'}}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="markdown">Markdown 报告</el-dropdown-item><el-dropdown-item command="archive" divided>离线归档（ZIP）</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="row.status==='completed'" link type="warning" @click="$emit('redetect')">重检</el-button><el-button v-if="row.status!=='processing'" link type="danger" @click="$emit('delete')">删除</el-button></div></template>
<script setup>defineProps({row:{type:Object,required:true},downloading:Boolean});defineEmits(['detail','report','redetect','delete'])</script>
<style scoped>.report-actions{display:flex;align-items:center;gap:2px;white-space:nowrap}</style>
